import sys,json,numpy as np
sys.path.insert(0,'/app/output')
from gen import r,CAMS,record,OUT

def get():
    return r.get_obs(cameras=CAMS,include_depth=True)

def step(actions,name):
    actions=np.asarray(actions,dtype=np.float64)
    np.save(OUT/f'{name}_actions.npy',actions)
    res=r.submit('ee_delta',actions,dt=r.spec()['control_dt'],cameras=CAMS,include_depth=True,video='both',note=name)
    record(res,name)
    return res

def current(obs):
    return np.array(obs.meta['proprio']['now'][:3])

def move(goal,grip,name,n=25,settle=12):
    obs=get();err=np.asarray(goal)-current(obs)
    a=np.r_[np.clip(err/(.01*n),-.6,.6),grip]
    actions=np.tile(a,(n,1))
    actions=np.r_[actions,np.tile([0,0,0,grip],(settle,1))]
    return step(actions,name)

if __name__=='__main__':
    mode=sys.argv[1]
    if mode=='move':
        move([float(v) for v in sys.argv[2:5]],float(sys.argv[5]),sys.argv[6],int(sys.argv[7]) if len(sys.argv)>7 else 25)
    elif mode=='hold':
        step(np.tile([0,0,0,float(sys.argv[2])],(int(sys.argv[3]),1)),sys.argv[4])
